def split_existing_names(apps, schema_editor):
    """Best-effort split of the existing single `full_name` string into
    name_first / name_father / name_grandfather for already-registered patients.
    Doctor accounts are untouched — this only walks Patient rows."""
    Patient = apps.get_model("clinic", "Patient")
    for patient in Patient.objects.select_related("user").all():
        full_name = (patient.user.full_name or "").strip()
        parts = full_name.split()
        patient.name_first = parts[0] if len(parts) > 0 else ""
        patient.name_father = parts[1] if len(parts) > 1 else ""
        patient.name_grandfather = " ".join(parts[2:]) if len(parts) > 2 else ""
        patient.save(update_fields=["name_first", "name_father", "name_grandfather"])


