def convert_height_and_recompute(apps, schema_editor):
    """Historical `height` values were stored in centimeters (e.g. 170).
    Convert them to meters (1.70) and recompute everything that's derived
    from height/activity so old records stay internally consistent with the
    new automatic formulas."""
    Assessment = apps.get_model("clinic", "Assessment")

    ACTIVITY_MULTIPLIERS = {"قليل": 1.375, "متوسط": 1.55, "عالي": 1.725}

    def bmi_class(bmi):
        if bmi < 18.5:
            return "نقص وزن"
        elif bmi < 25:
            return "طبيعي"
        elif bmi < 30:
            return "زيادة وزن"
        return "سمنة"

    def whr_class(whr, gender):
        if not whr:
            return ""
        if gender == "أنثى":
            if whr < 0.80:
                return "طبيعي"
            elif whr < 0.85:
                return "خطر متوسط"
            return "خطر عالي"
        if whr < 0.90:
            return "طبيعي"
        elif whr < 1.0:
            return "خطر متوسط"
        return "خطر عالي"

    def activity_level(days):
        try:
            days = int(days or 0)
        except (TypeError, ValueError):
            days = 0
        if days <= 1:
            return "قليل"
        elif days <= 4:
            return "متوسط"
        return "عالي"

    for a in Assessment.objects.select_related("patient").all():
        changed_fields = []

        # Heuristic: any stored height > 10 is still in centimeters (real
        # heights in meters are always well under 10). Convert once.
        if a.height and a.height > 10:
            a.height = round(a.height / 100, 2)
            changed_fields.append("height")

        if a.weight and a.height:
            a.bmi = round(a.weight / (a.height * a.height), 1)
            a.bmi_class = bmi_class(a.bmi)
            changed_fields += ["bmi", "bmi_class"]

        gender = a.patient.gender if a.patient_id else ""
        a.whr_class = whr_class(a.whr, gender)
        changed_fields.append("whr_class")

        a.activity_level = activity_level(a.sport_days_per_week)
        changed_fields.append("activity_level")

        if changed_fields:
            a.save(update_fields=list(dict.fromkeys(changed_fields)))


